        "if len(df_merged) < 3:\n",
        "    print(\"⚠️  Data overlap 2025 terlalu sedikit untuk regresi. Coba tambah dataset harga 2025.\")\n",
        "else:\n",
        "    X = df_merged[['total_produksi_ton', 'total_luas_panen_ha', 'avg_yield']].values\n",
        "    y = df_merged['harga'].values\n",
        "\n",
        "    # Random Forest Regressor\n",
        "    model = RandomForestRegressor(n_estimators=100, random_state=42)\n",
        "    model.fit(X, y)\n",
        "    y_pred = model.predict(X)\n",
        "\n",
        "    r2 = r2_score(y, y_pred)\n",
        "    mae = mean_absolute_error(y, y_pred)\n",
        "\n",
        "    print(f\"\\n=== HASIL REGRESI (Random Forest) ===\")\n",
        "    print(f\"R² Score : {r2:.4f}\")\n",
        "    print(f\"MAE      : Rp {mae:,.0f}/kg\")\n",
        "\n",
        "    # Feature importance\n",
        "    feat_names = ['Total Produksi', 'Luas Panen', 'Avg Yield']\n",
        "    importances = model.feature_importances_\n",
        "    plt.figure(figsize=(8, 4))\n",
        "    plt.barh(feat_names, importances, color=['#4CAF50', '#2196F3', '#FF9800'], alpha=0.85)\n",
        "    plt.title('Feature Importance → Harga Beras', fontweight='bold')\n",
        "    plt.xlabel('Importance Score')\n",
        "    plt.tight_layout()\n",
        "    plt.savefig('feature_importance.png', dpi=150)\n",
        "    plt.show()\n",
        "\n",
        "    # Actual vs Predicted\n",
        "    plt.figure(figsize=(10, 4))\n",
        "    plt.plot(df_merged['tanggal'], y, 'bo-', label='Harga Aktual', linewidth=2)\n",
        "    plt.plot(df_merged['tanggal'], y_pred, 'r--', label='Prediksi Model', linewidth=2)\n",
        "    plt.title('Harga Beras Medium I: Aktual vs Prediksi', fontweight='bold')\n",
